<template>
  <article class="sr-card" :class="{ selected }">
    <header class="sr-card-top">
      <div class="sr-identity">
        <span class="sr-id">طلب #{{ request.id }}</span>
        <h3 class="sr-name">{{ request.customerName }}</h3>
        <a v-if="request.customerPhone" class="sr-phone" :href="`tel:${request.customerPhone}`" dir="ltr">{{ request.customerPhone }}</a>
        <span v-else class="sr-missing">رقم الهاتف غير مسجل</span>
      </div>
      <span class="sr-status" :data-tab="request.tabKey">{{ request.statusLabel }}</span>
    </header>

    <dl class="sr-request-info">
      <div><dt>المنتج المطلوب</dt><dd>{{ request.requestedProduct || 'غير مسجل' }}</dd></div>
      <div><dt>العنوان</dt><dd>{{ request.address || 'غير مسجل' }}</dd></div>
    </dl>

    <dl class="sr-grid">
      <div><dt>موظف المبيعات</dt><dd>{{ request.targetEmployeeName || (request.targetEmployeeId ? `موظف #${request.targetEmployeeId}` : 'لم يُسند بعد') }}</dd></div>
      <div><dt>أُرسل بواسطة</dt><dd>{{ request.createdByName || 'غير مسجل' }}</dd></div>
      <div><dt>مصدر الطلب</dt><dd>{{ request.sourceTypeLabel || 'غير مسجل' }}</dd></div>
      <div><dt>الفرع والمحافظة</dt><dd>{{ request.branchName || `فرع #${request.branchId}` }}<span v-if="request.provinceName"> · {{ request.provinceName }}</span></dd></div>
      <div v-if="request.originalExternalId"><dt>مرجع المصدر</dt><dd>{{ request.originalExternalId }}</dd></div>
      <div v-if="request.linkedOrderId"><dt>رقم البيع المرتبط</dt><dd>#{{ request.linkedOrderId }}</dd></div>
    </dl>

    <div v-if="request.submissionNote" class="sr-note"><strong>ملاحظة المُرسل</strong><p>{{ request.submissionNote }}</p></div>
    <div v-if="request.lastStatusNote" class="sr-note"><strong>آخر ملاحظة على الطلب</strong><p>{{ request.lastStatusNote }}</p></div>
    <div v-if="request.rejectReason" class="sr-note sr-reason"><strong>سبب الرفض</strong><p>{{ request.rejectReason }}</p></div>
    <div v-if="request.deleteReason" class="sr-note sr-reason"><strong>سبب الحذف</strong><p>{{ request.deleteReason }}</p></div>

    <dl class="sr-times">
      <div><dt>تاريخ الإضافة</dt><dd>{{ formatDate(request.createdAt) }}</dd></div>
      <div><dt>آخر تغيير للحالة</dt><dd>{{ formatDate(request.statusChangedAtUtc) }}</dd><small>{{ formatDurationInStatus(request.statusChangedAtUtc, request.createdAt) }}</small></div>
    </dl>
    <slot name="matching" />
    <slot name="actions" />
    <button type="button" class="sr-open" :aria-expanded="!!selected" aria-haspopup="dialog" @click="$emit('select'); $emit('audit')">
      <span>{{ selected ? 'تفاصيل الطلب مفتوحة' : request.tabKey === 'unassigned' ? 'تدقيق الطلب ونتائج المطابقة' : 'تفاصيل الطلب وسجل الحركة' }}</span>
      <span aria-hidden="true">←</span>
    </button>
    <slot v-if="expanded" />
  </article>
</template>

<script setup lang="ts">
import { formatDurationInStatus, type SalesRequestListItem } from '../types'
defineProps<{ request: SalesRequestListItem; selected?: boolean; expanded?: boolean }>()
defineEmits<{ select: []; audit: [] }>()
function formatDate(value?: string | null) {
  if (!value || Number.isNaN(new Date(value).getTime())) return 'غير مسجل'
  return new Intl.DateTimeFormat('ar-IQ', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Baghdad' }).format(new Date(value))
}
</script>

<style scoped>
.sr-card { background:#fff; border:1px solid #dce7e5; border-radius:18px; padding:24px; color:#00201e; font-family:inherit; border-inline-start:4px solid #dce7e5; transition:border-color 180ms ease; overflow-wrap:anywhere; }
.sr-card.selected { border-color:#006a64; border-inline-start-color:#006a64; }
.sr-card-top { display:flex; align-items:flex-start; justify-content:space-between; gap:16px; }
.sr-identity { min-width:0; }
.sr-id { color:#526b67; font-size:14px; }
.sr-name { margin:6px 0; font-size:22px; line-height:1.65; font-weight:700; }
.sr-phone { display:inline-block; font-family:system-ui,sans-serif; font-size:18px; font-weight:600; color:#006a64; text-decoration:none; padding-block:4px; }
.sr-missing { color:#61756f; font-size:15px; }
.sr-status { flex-shrink:0; padding:7px 13px; border-radius:9px; background:#e9f3f0; color:#145c4c; font-size:14px; line-height:1.5; }
.sr-status[data-tab="unassigned"], .sr-status[data-tab="pending"] { background:#fff3d9; color:#79531a; }
.sr-status[data-tab="rejected"], .sr-status[data-tab="deleted"] { background:#fcebea; color:#963d35; }
.sr-request-info { background:#f3f7f6; border-radius:12px; padding:16px; margin:20px 0; display:grid; gap:14px; }
dt { color:#61756f; font-size:14px; margin-bottom:5px; }
dd { margin:0; font-size:16px; font-weight:600; line-height:1.75; white-space:pre-wrap; }
.sr-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:18px 24px; margin:0 0 18px; }
.sr-note { border-inline-start:3px solid #b5cec8; padding:10px 14px; margin-top:14px; background:#fafcfb; font-size:15px; line-height:1.8; }
.sr-note strong { font-size:14px; color:#526b67; }
.sr-note p { margin:4px 0 0; white-space:pre-wrap; }
.sr-reason { border-color:#cc8177; background:#fff8f6; }
.sr-times { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; border-top:1px solid #e3ebe8; padding-top:18px; margin:20px 0; }
.sr-times dd { font-size:14px; font-weight:400; }
.sr-times small { color:#61756f; font-size:13px; }
.sr-open { width:100%; display:flex; justify-content:space-between; align-items:center; gap:12px; background:#edf5f3; border:1px solid #cfdfda; border-radius:10px; color:#006a64; padding:13px 16px; min-height:48px; font-family:inherit; font-size:16px; font-weight:600; line-height:1.6; cursor:pointer; }
.sr-open:hover { background:#dfeee9; }
.sr-open:focus-visible,.sr-phone:focus-visible { outline:3px solid #006a64; outline-offset:3px; }
@media(max-width:480px) { .sr-card { padding:18px 15px; } .sr-name { font-size:21px; } .sr-card-top { flex-wrap:wrap; } .sr-grid { gap:16px 12px; } }
@media(prefers-reduced-motion:reduce) { .sr-card { transition:none; } }
</style>

